from datetime import datetime
from sqlalchemy import Column, Integer, Float, DateTime, String, Boolean, ForeignKey

from database import Base


class WastePrediction(Base):
    """Per product, per target-date forecast row generated by the forecasting service."""

    __tablename__ = "waste_predictions"

    id = Column(Integer, primary_key=True, index=True)
    owner_id = Column(Integer, ForeignKey("users.id"), index=True, nullable=False)
    item_id = Column(Integer, index=True, nullable=False)
    item_name = Column(String, nullable=True)
    category_id = Column(Integer, nullable=True)
    prediction_date = Column(DateTime, index=True, default=datetime.utcnow)
    target_date = Column(DateTime, index=True, nullable=False)
    predicted_demand = Column(Float, default=0.0)
    predicted_sales = Column(Float, default=0.0)
    predicted_surplus = Column(Float, default=0.0)
    predicted_waste = Column(Float, default=0.0)
    waste_probability = Column(Float, default=0.0)  # 0-1
    waste_risk_level = Column(String, default="low")
    expected_waste_value = Column(Float, default=0.0)
    expected_waste_pct = Column(Float, default=0.0)  # 0-100
    confidence = Column(Float, default=0.0)  # 0-1
    model_name = Column(String, default="rule_based_fallback")
    model_version = Column(String, default="1.0.0")
    is_fallback = Column(Boolean, default=False)
    method = Column(String, nullable=True)
    created_at = Column(DateTime, default=datetime.utcnow)